/*
# Create survey_benchmarks table (public reference dataset)

1. New Tables
  - `survey_benchmarks`
    - `respondent_id` (text, primary key) - unique ID from the source household survey
    - `state`, `zone`, `residence_type` (text) - location/demographic category of the household
    - `household_size` (int) - number of people in the household
    - `monthly_household_income` (text) - income bracket category
    - `primary_oil_type` (text) - main edible oil used by the household
    - `monthly_oil_purchase_litres` (numeric) - litres of oil bought per month
    - `deep_frying_frequency` (text) - how often the household deep fries
    - `oil_reuse_practice` (text) - how many times oil is reused before disposal
    - `health_awareness_score_1_10` (int) - self-reported health awareness score
    - `brand_price_preference` (text) - what drives the household's oil brand choice

2. Security
  - Enable RLS on `survey_benchmarks`.
  - Public-read for both anon and authenticated clients.

3. Notes
  - Seeded with 1200 real rows from the underlying household survey, inserted with
    ON CONFLICT (respondent_id) DO NOTHING.
*/

CREATE TABLE IF NOT EXISTS survey_benchmarks (
  respondent_id text PRIMARY KEY,
  state text NOT NULL,
  zone text NOT NULL,
  residence_type text NOT NULL,
  household_size int NOT NULL,
  monthly_household_income text NOT NULL,
  primary_oil_type text NOT NULL,
  monthly_oil_purchase_litres numeric NOT NULL,
  deep_frying_frequency text NOT NULL,
  oil_reuse_practice text NOT NULL,
  health_awareness_score_1_10 int NOT NULL,
  brand_price_preference text NOT NULL
);

ALTER TABLE survey_benchmarks ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "public_read_survey_benchmarks" ON survey_benchmarks;
CREATE POLICY "public_read_survey_benchmarks" ON survey_benchmarks FOR SELECT
TO anon, authenticated USING (true);

CREATE INDEX IF NOT EXISTS idx_survey_benchmarks_state_zone ON survey_benchmarks (state, zone);

INSERT INTO survey_benchmarks (
